// One clean record per chat message.
// Order number and email are taken with fixed patterns, not by the AI.
const j = $input.first().json;
const message = String(j.chatInput ?? '').trim();
const orderMatch = message.match(/\bSG-?(\d{5})\b/i);
const emailMatch = message.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);

return [{
  json: {
    channel: 'chat',
    session_id: 'chat:' + (j.sessionId || $execution.id),
    message,
    customer_name: null,
    customer_first_name: null,
    customer_email: emailMatch ? emailMatch[0].toLowerCase() : null,
    order_number: orderMatch ? 'SG-' + orderMatch[1] : null,
    attachment_names: [],
  },
}];

// One clean record per customer email. Code, not AI, decides who the customer is:
// the sender's address is the customer's email.
// Your support inbox: the Gmail account the trigger reads. The bot never answers its own emails.
const SUPPORT_ADDRESS = 'support@example.com';
const j = $input.first().json;

function sender(j) {
  const v = j.from && j.from.value && j.from.value[0];
  if (v && v.address) return { address: v.address, name: v.name || '' };
  const raw = String((j.from && j.from.text) || j.From || j.from || '');
  const m = raw.match(/^\s*"?([^"<]*?)"?\s*<([^>]+)>/);
  if (m) return { address: m[2], name: m[1].trim() };
  const e = raw.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return { address: e ? e[0] : '', name: '' };
}

function header(name) {
  const h = j.headers || {};
  const key = Object.keys(h).find(k => k.toLowerCase() === name);
  return key ? String(h[key]).replace(new RegExp('^' + name + ':\\s*', 'i'), '').trim() : '';
}

// Keep only the new part of the email: drop quoted history and lines starting with ">".
function newPart(text) {
  let t = String(text || '').replace(/\r\n/g, '\n');
  const cut = t.search(/^\s*(On [\s\S]{0,300}?wrote:\s*$|-{2,}\s*Original Message\s*-{2,}|From: .+\nSent: )/im);
  if (cut > 0) t = t.slice(0, cut);
  t = t.split('\n').filter(line => !/^\s*>/.test(line)).join('\n');
  return t.replace(/\n{3,}/g, '\n\n').trim().slice(0, 3000);
}

const from = sender(j);
const address = from.address.toLowerCase();
const subject = String(j.subject || j.Subject || '').trim();
const html = String(j.html || '');
const plain = j.text || html.replace(/<style[\s\S]*?<\/style>/gi, '').replace(/<[^>]+>/g, ' ').replace(/[ \t]+/g, ' ');
const body = newPart(plain) || String(j.snippet || '').trim();
const text = subject + '\n' + body;

// Never answer ourselves, no-reply senders, bounces or automatic replies.
let skipReason = null;
if (!address) skipReason = 'no sender address';
else if (address === SUPPORT_ADDRESS) skipReason = 'sent by Saltgrove';
else if (/^(no-?reply|do-?not-?reply|notifications?|mailer-daemon|postmaster|bounces?)[@+._-]/.test(address) || address.includes('noreply')) skipReason = 'no-reply sender';
else if (header('auto-submitted') && header('auto-submitted').toLowerCase() !== 'no') skipReason = 'automatic reply';

const orderMatch = text.match(/\bSG-?(\d{5})\b/i);

// Attachments (photos, receipts) are counted by code so the team is told when they arrive.
const files = Object.values($input.first().binary || {}).map(b => b.fileName || 'file');
const attachmentNote = files.length ? '\n\n[Attachments: ' + files.join(', ') + ']' : '';

return [{
  json: {
    channel: 'email',
    session_id: 'email:' + (j.threadId || j.id),
    message: 'Subject: ' + (subject || '(no subject)') + '\n\n' + body + attachmentNote,
    customer_name: from.name || null,
    customer_first_name: (from.name || '').trim().split(/\s+/)[0] || null,
    attachment_names: files,
    customer_email: address || null,
    order_number: orderMatch ? 'SG-' + orderMatch[1] : null,
    gmail_message_id: j.id,
    skip: skipReason !== null,
    skip_reason: skipReason,
  },
}];

// Shared by chat and email from here on.
// Is Customer Care open right now (Mon-Fri, 9 am-5 pm Pacific)? If not, when are they back?
// Code works this out so the agent never guesses. Public holidays are not handled yet.
const j = $input.first().json;
const pt = $now.setZone('America/Los_Angeles');
const isOpen = pt.weekday <= 5 && pt.hour >= 9 && pt.hour < 17;
let teamStatus;
if (isOpen) {
  teamStatus = 'open now, until 5:00 pm Pacific Time today';
} else {
  let next = pt.set({ hour: 9, minute: 0, second: 0, millisecond: 0 });
  if (pt.hour >= 9) next = next.plus({ days: 1 });
  while (next.weekday > 5) next = next.plus({ days: 1 });
  const day = next.toFormat('cccc, LLLL d');
  teamStatus = 'closed now, back ' + (next.hasSame(pt, 'day') ? 'today (' + day + ')' : day) + ' at 9:00 am Pacific Time';
}

return [{ json: { ...j, team_status: teamStatus, received_at: $now.toISO() } }];

// Code, not AI, decides who handles the message.
const base = $('Normalize').first().json;
const t = $input.first().json;
const o = (t && t.output && typeof t.output === 'object') ? t.output : null;
const triageFailed = !o || !o.category;

const category = triageFailed ? 'other' : o.category;
const urgency = triageFailed ? 'normal' : (o.urgency || 'normal');
const complaintTopic = ['complaint', 'refund_request'].includes(category)
  ? (o && o.complaint_topic && o.complaint_topic !== 'none' ? o.complaint_topic : 'other')
  : 'none';
const sensitive = !triageFailed && o.sensitive_topic === true;

// Spam is logged but never reaches the agent.
// First matching reason wins: urgent, sensitive_topic, order_change, refund_request, complaint.
const isSpam = category === 'spam';
// A person from the team already replied in this email thread: the agent is skipped and nothing is sent.
// Triage still runs, so an urgent message is still flagged for the team.
const human = !isSpam && base.human_takeover === true;
let reason = null;
if (!isSpam) {
  if (urgency === 'urgent') reason = 'urgent';
  else if (sensitive) reason = 'sensitive_topic';
  else if (['order_change', 'refund_request', 'complaint'].includes(category)) reason = category;
}

let brief;
if (reason) {
  brief = `This message has ALREADY been passed to the Customer Care team (reason: ${reason}${urgency === 'urgent' ? ', urgent' : ''}). `
    + 'Write a short holding reply that follows HANDING OFF TO THE TEAM. You may search the help documents for steps that apply '
    + '(for example skin reaction safety steps, or what to send for a damaged item), but promise no outcome. Do not add a handoff marker.'
    // The team can only reply by email: in chat without an email, the agent must ask for one.
    + (base.channel !== 'email' && !base.customer_email
      ? ' This is a chat message without an email address: unless the customer gave one earlier in this conversation, ask for the best email to reach them.'
      : '');
} else if (triageFailed) {
  brief = 'The message could not be sorted automatically. If it is a simple question, answer it from the help documents. '
    + 'If it is a complaint, a refund or order change, a health or skin issue, or anything you cannot answer from the documents, '
    + 'write a holding reply and end with [[HANDOFF:not_in_docs]].';
} else {
  brief = 'Answer this message. Search the help documents before answering anything about products or policies. '
    + 'Use lookup_order for order status.';
}

return [{
  json: {
    ...base,
    category,
    urgency,
    complaint_topic: complaintTopic,
    sensitive_topic: sensitive,
    summary: o && o.summary ? o.summary : '',
    route_decision: isSpam ? 'spam' : (human ? 'human' : (reason ? 'escalate' : 'answer')),
    escalation_reason: reason,
    triage_failed: triageFailed,
    agent_brief: brief,
  },
}];

// Reads the [[HANDOFF:...]] marker, removes it from the reply, and sets the final route.
// Spam, and emails in a thread a person is handling, arrive straight from "Skip Agent?"
// and never went through the agent.
const r = $('Route').first().json;
const a = $input.first().json;

if (r.route_decision === 'spam') {
  return [{
    json: {
      ...r,
      // Chat needs something on screen; spam email gets no reply at all.
      reply: r.channel === 'chat' ? 'Thanks for reaching out. This chat only helps with Saltgrove Skin orders and products.' : '',
      route: 'spam',
      escalation_reason: null,
      handoff_marker: null,
      agent_failed: false,
    },
  }];
}

if (r.route_decision === 'human') {
  return [{
    json: {
      ...r,
      reply: '',
      route: 'human',
      handoff_marker: null,
      agent_failed: false,
    },
  }];
}

const raw = typeof a.output === 'string' ? a.output : '';
const agentFailed = raw.trim() === '';

const marker = raw.match(/\[\[\s*HANDOFF\s*:\s*([a-z_]+)\s*\]\]/i);
const markerReason = marker ? marker[1].toLowerCase() : null;
let reply = raw.replace(/\[\[\s*HANDOFF\s*:[^\]]*\]\]/gi, '').trim();

let route, reason;
if (r.route_decision === 'escalate') {
  route = 'escalated'; reason = r.escalation_reason;
} else if (['not_in_docs', 'asked_for_human'].includes(markerReason)) {
  route = 'escalated'; reason = markerReason;
} else if (agentFailed) {
  route = 'error'; reason = null;
} else {
  route = 'answered'; reason = null;
}

// If the agent failed, still give an honest reply. An escalated message still reaches the team.
if (agentFailed) {
  reply = route === 'escalated'
    ? "Thanks for your message. I've passed it to our Customer Care team, and they'll reply by email within 1 business day. "
      + (r.customer_email ? '' : 'Please reply with the best email address to reach you.')
    : (r.channel === 'email'
      ? '' // no email is sent; "Collect Alerts" asks a person to reply
      : "Sorry, I couldn't process your message just now. Please try again in a moment.");
  reply = reply.trim();
}

return [{
  json: {
    ...r,
    reply,
    route,
    escalation_reason: reason,
    handoff_marker: markerReason,
    agent_failed: agentFailed,
  },
}];

// What does this message mean for the conversation's ticket? One conversation = one ticket.
// create         : passed to the team, no ticket yet in this conversation
// escalate_again : the conversation has a ticket and this message is urgent or has a new reason
// attachments    : the conversation has a ticket and the customer sent files (photos, receipts)
// add_email      : the conversation has a ticket and the customer just gave an email
// append         : any other message in a conversation that has a ticket (saved quietly),
//                  including emails in a thread a person is handling (their Slack note comes from "Collect Alerts")
// none           : no ticket involved
const h = $('Check Handoff').first().json;
const s = $input.first().json || {};

const sessionTicket = s.session_ticket_id || null;
const email = h.customer_email || s.session_email || null;
const order = h.order_number || s.session_order || null;
const emailIsNew = !!h.customer_email && h.customer_email !== s.session_email;
const orderIsNew = !!h.order_number && h.order_number !== s.session_order;

const replyText = h.reply
  || (h.route === 'human' ? '(no reply from the bot: a person from the team is handling this thread)' : '')
  || (h.route === 'error' ? '(no reply sent: the AI could not answer)' : '');
const transcript = [s.transcript, '[Customer] ' + h.message + '\n[Assistant] ' + replyText]
  .filter(Boolean)
  .join('\n');

// A follow-up only reaches Slack when it is urgent, has a reason not seen before in this
// conversation, brings attachments, or brings the email the team was waiting for.
const reasons = String(s.session_reasons || '').split(',').filter(Boolean);
const reasonIsNew = !!h.escalation_reason && !reasons.includes(h.escalation_reason);
const files = h.attachment_names || [];
const followUp = files.length ? 'attachments' : (emailIsNew ? 'add_email' : 'append');

let action = 'none';
if (h.route === 'escalated') {
  if (!sessionTicket) action = 'create';
  else if (h.urgency === 'urgent' || reasonIsNew) action = 'escalate_again';
  else action = followUp;
} else if (h.route === 'human') {
  action = sessionTicket ? 'append' : 'none';
} else if (sessionTicket && h.route !== 'spam') {
  action = followUp;
}

return [{
  json: {
    ...h,
    email,
    order,
    email_is_new: emailIsNew,
    order_is_new: orderIsNew,
    session_ticket_id: sessionTicket,
    transcript,
    ticket_action: action,
  },
}];

// Airtable fields for a new ticket, or the changes for the conversation's existing ticket.
// Field names and select options must match the Tickets table exactly (see the README).
const p = $('Ticket Plan').first().json;

const others = $input.all()
  .map(i => i.json)
  .filter(r => r && typeof r.id === 'string' && r.id.startsWith('rec'));
const otherTickets = others
  .map(r => '#' + (r.Ticket ?? (r.fields && r.fields.Ticket) ?? '?'))
  .join(', ');

// Escalations from low-urgency messages are recorded as normal.
const urgency = p.urgency === 'urgent' ? 'urgent' : 'normal';

if (p.ticket_action === 'create') {
  const fields = {
    'Status': 'Open',
    'Urgency': urgency,
    'Category': p.category,
    'Topic': p.complaint_topic || 'none',
    'Escalation reason': p.escalation_reason,
    'Channel': p.channel,
    'Summary': p.summary || '(no summary: triage failed)',
    'Customer message': p.transcript,
    'AI reply sent': p.reply,
    'Session ID': p.session_id,
  };
  if (p.customer_name) fields['Customer name'] = p.customer_name;
  if (p.email) fields['Customer email'] = p.email;
  if (p.order) fields['Order number'] = p.order;
  if (otherTickets) fields['Other open tickets'] = otherTickets;
  return [{ json: fields }];
}

// escalate_again, add_email, append: update the existing ticket.
const changes = { id: p.session_ticket_id, 'Customer message': p.transcript };
if (p.email_is_new) changes['Customer email'] = p.email;
if (p.order_is_new) changes['Order number'] = p.order;
if (p.ticket_action === 'escalate_again' && urgency === 'urgent') changes['Urgency'] = 'urgent';
if (otherTickets) changes['Other open tickets'] = otherTickets;
return [{ json: changes }];

// Text for #support-escalations. URGENT comes first; every alert links to the ticket.
// Quiet updates (the customer just kept chatting) are saved on the ticket without a Slack message.
const p = $('Ticket Plan').first().json;
const rec = $input.first().json || {};
const saved = typeof rec.id === 'string' && rec.id.startsWith('rec');
const f = rec.fields || rec;
const num = f.Ticket ?? '?';
const other = f['Other open tickets'];
const urgent = p.urgency === 'urgent';
const who = p.email ? (p.customer_name ? p.customer_name + ' (' + p.email + ')' : p.email) : 'email not given yet';
const files = p.attachment_names || [];
const filesLine = files.length ? ':paperclip: ' + files.length + ' attachment(s): ' + files.join(', ') : '';
const link = saved
  ? '<https://airtable.com/YOUR_AIRTABLE_BASE_ID/YOUR_TICKETS_TABLE_ID/' + rec.id + '|Open ticket #' + num + ' in Airtable>'
  : '';
const lines = [];

if (!saved) {
  lines.push(':warning: *A ticket could not be saved to Airtable.* Check n8n execution ' + $execution.id + '.');
  lines.push('Customer: ' + who + ' · Action: ' + p.ticket_action + ' · Reason: ' + (p.escalation_reason || '-'));
  lines.push('> ' + p.message);
  return [{ json: { notify: true, text: lines.join('\n') } }];
}

if (p.ticket_action === 'create') {
  lines.push((urgent ? ':rotating_light: *URGENT* · ' : '') + '*New ticket #' + num + '* · ' + p.escalation_reason);
  lines.push('*Category:* ' + p.category + ' · *Topic:* ' + p.complaint_topic + ' · *Channel:* ' + p.channel);
  lines.push('*Customer:* ' + who + (p.order ? ' · *Order:* ' + p.order : ''));
  lines.push('*Summary:* ' + (p.summary || '(none)'));
  if (other) lines.push(':link: This customer also has open ticket(s): ' + other);
  if (filesLine) lines.push(filesLine);
  lines.push(link);
} else if (p.ticket_action === 'escalate_again') {
  lines.push((urgent ? ':rotating_light: *URGENT* · ' : '') + '*Ticket #' + num + ':* new message from the customer that needs the team (' + p.escalation_reason + ').');
  lines.push('*Summary:* ' + (p.summary || '(none)'));
  if (filesLine) lines.push(filesLine);
  lines.push(link);
} else if (p.ticket_action === 'attachments') {
  lines.push(':paperclip: *Ticket #' + num + ':* the customer sent ' + files.length + ' attachment(s) by email (' + files.join(', ') + '). Ready for review.');
  lines.push(link);
} else if (p.ticket_action === 'add_email') {
  lines.push('*Ticket #' + num + ':* customer email added (' + p.email + '). Ready for a reply.');
  if (other) lines.push(':link: This customer also has open ticket(s): ' + other);
  lines.push(link);
} else {
  return [{ json: { notify: false, text: '' } }];
}
return [{ json: { notify: true, text: lines.join('\n') } }];

// Only the columns of the support_messages table, plus the ticket this conversation belongs to.
const p = $('Ticket Plan').first().json;
let ticketId = p.session_ticket_id || null;
if ($('Create Ticket').isExecuted) {
  const rec = $('Create Ticket').first().json || {};
  if (typeof rec.id === 'string' && rec.id.startsWith('rec')) ticketId = rec.id;
}
return [{
  json: {
    channel: p.channel,
    session_id: p.session_id,
    customer_name: p.customer_name,
    customer_email: p.customer_email,
    order_number: p.order_number,
    message: p.message,
    category: p.category,
    urgency: p.urgency,
    complaint_topic: p.complaint_topic,
    sensitive_topic: p.sensitive_topic,
    route: p.route,
    escalation_reason: p.escalation_reason,
    ai_reply: p.reply || null,
    ticket_id: ticketId,
    execution_id: String($execution.id),
  },
}];

