parameters.jsCode:
// Has a person from the team already replied in this email thread?
// Every bot reply gets the Gmail label "AI reply" right after it is sent (see "Label AI Reply").
// A sent message in the thread without that label was written by a person, so the bot stays quiet.
// (Checking the footer text would not work: a person's reply quotes the bot's earlier email, footer included.)
const AI_LABEL = 'YOUR_AI_REPLY_LABEL_ID';
const email = $('Read Email').first().json;
const items = $input.all().map(i => i.json || {});
const threadCheckFailed = items.some(i => i.error);
const messages = items
  .flatMap(i => (Array.isArray(i.messages) ? i.messages : [i]))
  .filter(m => m && m.id);
const labelsOf = m => [
  ...(Array.isArray(m.labelIds) ? m.labelIds : []),
  ...(Array.isArray(m.labels) ? m.labels.map(l => l.id) : []),
];
const personReplies = messages.filter(m => {
  const labels = labelsOf(m);
  return labels.includes('SENT') && !labels.includes(AI_LABEL);
});

return [{
  json: {
    ...email,
    human_takeover: personReplies.length > 0,
    thread_check_failed: threadCheckFailed,
  },
}];

// Problems the workflow caught so the customer still got an answer, and emails a person is handling.
// Someone must act for a customer  -> #support-escalations.
// The workflow needs a look        -> #automation-errors.
// At most one Slack message per run. Crashes are reported by the Error workflow instead.
const SUPPORT = 'YOUR_SUPPORT_ESCALATIONS_CHANNEL_ID';  // #support-escalations
const ERRORS = 'YOUR_AUTOMATION_ERRORS_CHANNEL_ID';   // #automation-errors
const p = $('Ticket Plan').first().json;

const ran = name => { try { return $(name).isExecuted; } catch (e) { return false; } };
const failed = name => ran(name) && $(name).all().some(i => i.json && i.json.error);

const who = (p.customer_name ? p.customer_name + ' ' : '') + (p.email ? '(' + p.email + ')' : '(email not given)');
const subject = (String(p.message || '').match(/^Subject: (.*)$/m) || [])[1] || '(no subject)';
const preview = String(p.message || '').replace(/^Subject: .*\n+/, '').replace(/\s+/g, ' ').trim().slice(0, 200);

const tech = [];
if (p.thread_check_failed) tech.push('Could not read the email thread, so the bot could not check whether a person had already replied.');
if (p.triage_failed) tech.push('Triage failed, so the message was sorted by the fallback rules.');
if (p.agent_failed) tech.push('The AI agent failed' + (p.route === 'escalated' ? '; a fixed holding reply was sent instead.' : '.'));
if (failed('Session Lookup')) tech.push('Looking up this conversation in Supabase failed.');
if (failed('Find Other Open Tickets')) tech.push("Checking the customer's other open tickets failed.");
if (failed('Slack: #support-escalations')) tech.push('The alert to #support-escalations could not be posted.');
if (failed('Log Message')) tech.push('The message was not saved to support_messages.');

const lines = [];
let channel = ERRORS;

if (p.channel === 'email' && p.route === 'error') {
  channel = SUPPORT;
  lines.push(':warning: *This customer has not received a reply.* The AI could not answer the email, so nothing was sent. Please reply in Gmail yourself.');
  lines.push('*Customer:* ' + who + ' · *Subject:* ' + subject);
  lines.push('> ' + preview);
} else if (p.route === 'human') {
  channel = SUPPORT;
  let ticket = '';
  let link = '';
  if (ran('Update Ticket')) {
    const rec = $('Update Ticket').first().json || {};
    if (typeof rec.id === 'string' && rec.id.startsWith('rec')) {
      ticket = '*Ticket #' + ((rec.fields || rec).Ticket ?? '?') + ':* ';
      link = '<https://airtable.com/YOUR_AIRTABLE_BASE_ID/YOUR_TICKETS_TABLE_ID/' + rec.id + '|Open the ticket in Airtable>';
    }
  }
  lines.push((p.urgency === 'urgent' ? ':rotating_light: *URGENT* · ' : '') + ':speech_balloon: ' + ticket
    + 'the customer replied in an email thread a person from the team is handling. The bot did not reply.');
  lines.push('*Customer:* ' + who + ' · *Subject:* ' + subject);
  lines.push('*Summary:* ' + (p.summary || preview));
  const files = p.attachment_names || [];
  if (files.length) lines.push(':paperclip: ' + files.length + ' attachment(s): ' + files.join(', '));
  if (link) lines.push(link);
}

if (tech.length) {
  lines.push(lines.length
    ? '_Problems in this run (execution ' + $execution.id + '):_'
    : ':gear: *Problems while handling ' + (p.channel === 'email' ? 'an email' : 'a chat message') + '* (execution ' + $execution.id + ', customer ' + who + ')');
  tech.forEach(t => lines.push('• ' + t));
}

return [{ json: { send: lines.length > 0, channel, text: lines.join('\n') } }];

// Was the email reply sent, and labelled "AI reply"? The label is how the bot later tells
// its own replies apart from a person's replies in the same thread.
// Nothing to report -> no item, and the run ends here.
const AI_LABEL = 'YOUR_AI_REPLY_LABEL_ID';
const SUPPORT = 'YOUR_SUPPORT_ESCALATIONS_CHANNEL_ID';  // #support-escalations
const ERRORS = 'YOUR_AUTOMATION_ERRORS_CHANNEL_ID';   // #automation-errors
const p = $('Ticket Plan').first().json;
const sent = $('Gmail: Reply in Thread').first().json || {};
const labelled = $input.first().json || {};
const who = (p.customer_name ? p.customer_name + ' ' : '') + '(' + (p.email || p.customer_email || 'unknown') + ')';
const subject = (String(p.message || '').match(/^Subject: (.*)$/m) || [])[1] || '(no subject)';

if (!sent.id) {
  return [{ json: { channel: SUPPORT, text: [
    ':warning: *This customer has not received a reply.* The email reply could not be sent. Please reply in Gmail yourself.',
    '*Customer:* ' + who + ' · *Subject:* ' + subject,
    '_Execution ' + $execution.id + ': ' + String(sent.error || 'unknown error').slice(0, 200) + '_',
  ].join('\n') } }];
}

const labels = Array.isArray(labelled.labelIds) ? labelled.labelIds : [];
if (!labels.includes(AI_LABEL)) {
  return [{ json: { channel: ERRORS, text: [
    ':label: The bot replied to ' + who + ' (subject: ' + subject + '), but the reply could not be labelled "AI reply" (execution ' + $execution.id + ').',
    'Add the label to that reply in Gmail by hand. Without it, the bot treats the reply as written by a person and stays quiet in that thread.',
  ].join('\n') } }];
}

return [];

// Eval mode: one test case sent by "Saltgrove – Eval Runner", shaped like Read Chat / Read Email.
// The case then goes through the same Normalize, triage, Route and agent as real messages.
// "Eval Run?" stops it right after Check Handoff: no ticket, Slack, email or log row.
const c = $input.first().json;
const run = String(c.run_id || 'manual');
const isEmail = c.channel === 'email';
const body = String(c.message || '').trim();
const message = isEmail ? 'Subject: ' + (c.subject || '(no subject)') + '\n\n' + body : body;
const orderMatch = message.match(/\bSG-?(\d{5})\b/i);
const emailMatch = isEmail ? null : message.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
const name = isEmail && c.customer_name ? String(c.customer_name).trim() : null;

return [{
  json: {
    channel: isEmail ? 'email' : 'chat',
    // A fresh conversation memory for every run; cases with the same session (3a/3b, 6a/6b) share it.
    session_id: 'eval:' + run + ':' + (c.session || c.case_id),
    message,
    customer_name: name,
    customer_first_name: name ? name.split(/\s+/)[0] : null,
    customer_email: isEmail ? String(c.customer_email || '').toLowerCase() || null : (emailMatch ? emailMatch[0].toLowerCase() : null),
    order_number: orderMatch ? 'SG-' + orderMatch[1] : null,
    attachment_names: [],
    human_takeover: false,
    thread_check_failed: false,
    eval: true,
    eval_run_id: run,
    eval_case_id: String(c.case_id),
  },
}];

// Eval mode ends here. This item goes back to the Eval Runner, which checks it.
const r = $input.first().json;
return [{
  json: {
    case_id: r.eval_case_id,
    run_id: r.eval_run_id,
    route: r.route,
    escalation_reason: r.escalation_reason || null,
    category: r.category,
    urgency: r.urgency,
    complaint_topic: r.complaint_topic,
    sensitive_topic: r.sensitive_topic === true,
    triage_failed: r.triage_failed === true,
    agent_failed: r.agent_failed === true,
    team_status: r.team_status,
    reply: r.reply || '',
    execution_id: String($execution.id),
  },
}];
